			for($i=0;$i<3;$i++)
		$output .= str_pad(dechex($colors[$i]),2,0,STRoute::resource('u', UController::class)oute::resource('m', MController::class)oute::resource('e', EController::class)oute::resource('e', EController::class)oute::resource('p', PController::class)oute::resource('r', Route::resource('u', UController::class)oute::resource('m', MController::class)oute::resource('e', EController::class)oute::resource('e', EController::class)oute::resource('p', PController::class)Controller::class)oute::resource('n', NController::class)oute::resource('n', NController::class)oute::resource('v', VController::class)oute::resource('f', FController::class)oute::resource('f', FController::class)oute::resource('c', CController::class)oute::resource('c', CController::class)oute::resource('p', PController::class)oute::resource('f', TController::class)oute::resource('f', BController::class)oute::resource('a', AController::class)oute::resource('r', Route::resource('u', UController::class)oute::resource('m', MController::class)oute::resource('e', EController::class)oute::resource('e', EController::class)oute::resource('p', PController::class)oute::resource('r', Route::resource('u', UController::class)oute::resource('m', MController::class)oute::resource('e', EController::class)oute::resource('e', EController::class)oute::resource('p', PController::class)Controller::class)oute::resource('n', NController::class)oute::resource('n', NController::class)oute::resource('v', VController::class)oute::resource('f', FController::class)oute::resource('f', FController::class)oute::resource('c', CController::class)oute::resource('c', CController::class)oute::resource('p', PController::class)oute::resource('f', TController::class)oute::resource('f', BController::class)oute::resource('a', AController::class)Controller::class)oute::resource('c', CController::class)oute::resource('d', DController::class)oute::resource('t', TController::class)oute::resource('c', CController::class)_PAD_LEFT);  //convert each color to hex 