		date_default_timezone_set("America/Sao_Paulo");                  
		$nome = Confide::user() ? Confide::user()->username : '';
		$hr = date(" H ");           

		if($hr >= 12 && $hr < 20) {  
			$turno = "Boa tarde";  
		}else if ($hr >= 20 && $hr <  24){  
			$turno = "Boa noite";  
		}else if ($hr >= 0 && $hr <  6){  
			$turno = "Dormir é para os fracos \o/";  
		}else if ($hr >= 6 && $hr <12 ){  
			$turno = "Bom dia";  
		}else{  
			$turno = "Que horas são?";  
		}           

		return  $turno;  
