			$valor = str_replace( ',', '.', $valor );
			$valor = number_format( $valor, 2, '.', '');      
			return $valor;
		}

		public static function bonito($valor){
			$valor = number_format( (float)$valor, 2, ',', '.');
			return $valor;
		}

		public static function igual($valor){
			$valor = $valor;
			return $valor;
		}

	  }



